class Solution {
    public int[][] nearestStations(int[][] stations, int k) {
        int[][] a = stations.clone();
        Arrays.sort(a, (p, q) -> {
            int dp = p[0] * p[0] + p[1] * p[1], dq = q[0] * q[0] + q[1] * q[1];
            if (dp != dq) return Integer.compare(dp, dq);
            return p[0] != q[0] ? Integer.compare(p[0], q[0]) : Integer.compare(p[1], q[1]);
        });
        return Arrays.copyOf(a, k);
    }
}

