typedef struct { int d, x, y; } Key;

static int by_key(const void* p, const void* q) {
    const Key *a = p, *b = q;
    if (a->d != b->d) return (a->d > b->d) - (a->d < b->d);
    if (a->x != b->x) return (a->x > b->x) - (a->x < b->x);
    return (a->y > b->y) - (a->y < b->y);
}

int** nearestStations(int** stations, int stationsSize, int* stationsColSize, int k, int* returnSize, int** returnColumnSizes) {
    Key* keys = malloc(stationsSize * sizeof(Key));
    for (int i = 0; i < stationsSize; i++) {
        int x = stations[i][0], y = stations[i][1];
        keys[i] = (Key){x * x + y * y, x, y};
    }
    qsort(keys, stationsSize, sizeof(Key), by_key);
    int** out = malloc(k * sizeof(int*));
    *returnColumnSizes = malloc(k * sizeof(int));
    for (int i = 0; i < k; i++) {
        out[i] = malloc(2 * sizeof(int));
        out[i][0] = keys[i].x;
        out[i][1] = keys[i].y;
        (*returnColumnSizes)[i] = 2;
    }
    free(keys);
    *returnSize = k;
    return out;
}

