class Solution {
    private final Random rng = new Random(11);

    private static int compare(int[] p, int[] q) {
        if (p[0] != q[0]) return Integer.compare(p[0], q[0]);
        if (p[1] != q[1]) return Integer.compare(p[1], q[1]);
        return Integer.compare(p[2], q[2]);
    }

    public int[][] nearestStations(int[][] stations, int k) {
        int n = stations.length;
        int[][] a = new int[n][];
        for (int i = 0; i < n; i++) a[i] = new int[] {stations[i][0] * stations[i][0] + stations[i][1] * stations[i][1], stations[i][0], stations[i][1]};
        int lo = 0, hi = n - 1, target = k - 1;
        while (lo < hi) {
            int[] p = a[lo + rng.nextInt(hi - lo + 1)];
            int lt = lo, i = lo, gt = hi;
            while (i <= gt) {
                int c = compare(a[i], p);
                if (c < 0) { int[] t = a[lt]; a[lt++] = a[i]; a[i++] = t; }
                else if (c > 0) { int[] t = a[gt]; a[gt--] = a[i]; a[i] = t; }
                else i++;
            }
            if (target < lt) hi = lt - 1;
            else if (target > gt) lo = gt + 1;
            else break;
        }
        int[][] first = Arrays.copyOf(a, k);
        Arrays.sort(first, Solution::compare);
        int[][] out = new int[k][];
        for (int i = 0; i < k; i++) out[i] = new int[] {first[i][1], first[i][2]};
        return out;
    }
}

